+    var k = String(ticketKey == null ? '' : ticketKey);
+    var composite = /^[\w.-]+\/[\w.-]+#(\d+)$/.exec(k);
+    if (composite) return 'gh-' + composite[1];
+    return k.replace(/[^A-Za-z0-9._-]/gu, '-');
+}
